class Solution:
    def mySqrt(self, x: int) -> int:
        # Handle edge cases
        if x == 0:
            return 0

        # Binary search for the square root
        left = 1
        right = x

        while left <= right:
            mid = (left + right) // 2
            square = mid * mid

            if square == x:
                return mid
            elif square < x:
                # mid could be the answer, but we want the largest such number
                left = mid + 1
            else:
                # mid is too large, search in left half
