def optimalDivision(nums):
    n = len(nums)

    if n == 1:
        return str(nums[0])
    elif n == 2:
        return f"{nums[0]}/{nums[1]}"
    else:
        # For n >= 3, the optimal is nums[0]/(nums[1]/nums[2]/.../nums[n-1])
        # We need to format the denominator without redundant parentheses
        denominator = "/".join(map(str, nums[1:]))
        return f"{nums[0]}/({denominator})"

class Solution:
    def isIdealPermutation(self, nums: List[int]) -> bool:
        for i in range(len(nums)):
            if abs(nums[i] - i) > 1:
                return False
        return True

def calculate(s: str) -> int:
    # Remove spaces
    s = s.replace(" ", "")

    stack = []
    num = 0
    operator = '+'  # Start with + to handle the first number

    for i in range(len(s)):
        char = s[i]

        # Build number if current character is a digit
        if char.isdigit():
            num = num * 10 + int(char)

        # Process when we encounter an operator or reach the end
        if not char.isdigit() or i == len(s) - 1:
            if operator == '+':
                stack.append(num)
            elif operator == '-':
                stack.append(-num)
            elif operator == '*':
                stack.append(stack.pop() * num)
            elif operator == '/':
                # Handle truncation toward zero for negative numbers
                prev = stack.pop()
                if prev < 0:
                    stack.append(-(-prev // num))
                else:
                    stack.append(prev // num)

            # Update operator and reset num
            operator = char
            num = 0

    return sum(stack)

def minSteps(n):
    if n == 1:
        return 0

    # Find sum of all prime factors of n
    result = 0
    d = 2

    while d * d <= n:
        while n % d == 0:
            result += d
            n //= d
        d += 1

    # If n is still greater than 1, it's a prime factor
    if n > 1:
        result += n

    return result

def reorderedPowerOf2(n: int) -> bool:
    # Convert n to string to work with digits
    n_str = str(n)
    n_digits = len(n_str)

    # Generate all powers of 2 that have the same number of digits as n
    # We need to find powers of 2 that have exactly n_digits
    powers_of_2 = []
    power = 1
    while len(str(power)) <= n_digits:
        if len(str(power)) == n_digits:
            powers_of_2.append(power)
        power *= 2

    # Convert n to digit frequency count
    n_digit_count = {}
    for digit in n_str:
        n_digit_count[digit] = n_digit_count.get(digit, 0) + 1

    # Check each power of 2
    for power in powers_of_2:
        power_str = str(power)
        power_digit_count = {}
        for digit in power_str:
            power_digit_count[digit] = power_digit_count.get(digit, 0) + 1

        # Check if digit frequencies match
        if n_digit_count == power_digit_count:
            return True

    return False

def maximumSwap(num):
    # Convert number to list of digits
    digits = list(str(num))
    n = len(digits)

    # For each digit from left to right
    for i in range(n):
        # Find the maximum digit to the right of position i
        max_digit = digits[i]
        max_pos = i

        for j in range(i + 1, n):
            if digits[j] > max_digit:
                max_digit = digits[j]
                max_pos = j

        # If we found a larger digit to the right, swap and return
        if max_digit > digits[i]:
            # Swap with the rightmost occurrence of max_digit
            digits[i], digits[max_pos] = digits[max_pos], digits[i]
            return int(''.join(digits))

    # No swap needed, return original number
    return num

def superPow(a, b):
    MOD = 1337

    def pow_mod(base, exp):
        """Calculate (base^exp) % MOD efficiently"""
        result = 1
        base = base % MOD
        while exp > 0:
            if exp % 2 == 1:
                result = (result * base) % MOD
            exp = exp >> 1
            base = (base * base) % MOD
        return result

    def pow_10_mod(base):
        """Calculate (base^10) % MOD"""
        return pow_mod(base, 10)

    result = 1
    for digit in b:
        # result = (result^10) * (a^digit) mod MOD
        result = (pow_10_mod(result) * pow_mod(a, digit)) % MOD

    return result

def baseNeg2(n):
    if n == 0:
        return "0"

    result = ""

    while n != 0:
        # Get remainder when dividing by -2
        remainder = n % (-2)

        # If remainder is negative, adjust it
        if remainder < 0:
            remainder += 2
            n = n // (-2) + 1
        else:
            n = n // (-2)

        result = str(remainder) + result

    return result

import math

def numberOfBoomerangs(points):
    def distance(p1, p2):
        return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

    total_boomerangs = 0

    # For each point as the center
    for i in range(len(points)):
        # Dictionary to store distance -> count
        distance_count = {}

        # Calculate distance from current point to all other points
        for j in range(len(points)):
            if i != j:  # Don't calculate distance to itself
                dist = distance(points[i], points[j])
                distance_count[dist] = distance_count.get(dist, 0) + 1

        # For each distance, if there are 'count' points at that distance,
        # we can form count * (count - 1) boomerangs
        for count in distance_count.values():
            if count >= 2:
                total_boomerangs += count * (count - 1)

    return total_boomerangs

def rotatedDigits(n):
    # Define rotation mapping
    rotation_map = {
        '0': '0',
        '1': '1',
        '2': '5',
        '5': '2',
        '6': '9',
        '8': '8',
        '9': '6'
    }

    def is_good(num):
        num_str = str(num)
        rotated = ""

        # Check if all digits are valid and build rotated number
        for digit in num_str:
            if digit not in rotation_map:
                return False  # Invalid digit (3, 4, 7)
            rotated += rotation_map[digit]

        # Check if rotated number is different from original
        return rotated != num_str

    count = 0
    for i in range(1, n + 1):
        if is_good(i):
            count += 1

    return count

