def nearestPalindromic(n: str) -> str:
    num = int(n)
    length = len(n)

    # Special case: single digit
    if length == 1:
        return str(num - 1) if num > 1 else "0"

    # Generate candidate palindromes
    candidates = []

    # Candidate 1: Palindrome formed by mirroring left half
    left_half = n[:length // 2 + length % 2]
    if length % 2 == 1:
        # Odd length: mirror left half without the middle digit
        palindrome = left_half + left_half[-2::-1]
    else:
        # Even length: mirror left half
        palindrome = left_half + left_half[::-1]
    candidates.append(int(palindrome))

    # Candidate 2: Decrease left half by 1
    left_half_num = int(left_half)
    new_left_half = str(left_half_num - 1)

    # Handle borrowing (e.g., 100 -> 99)
    if len(new_left_half) < len(left_half):
        # This creates a palindrome like 99...9
        if length % 2 == 1:
            palindrome = new_left_half + new_left_half[-2::-1]
        else:
            palindrome = new_left_half + new_left_half[::-1]
        # But we need to make it the right length
        if length % 2 == 1:
            palindrome = new_left_half + '9' * (length - len(new_left_half) - 1) + new_left_half[-2::-1]
        else:
            palindrome = new_left_half + '9' * (length - len(new_left_half)) + new_left_half[::-1]
        candidates.append(int(palindrome))
    else:
        if length % 2 == 1:
            palindrome = new_left_half + new_left_half[-2::-1]
        else:
            palindrome = new_left_half + new_left_half[::-1]
        candidates.append(int(palindrome))

    # Candidate 3: Increase left half by 1
    new_left_half = str(left_half_num + 1)
    if len(new_left_half) > len(left_half):
        # This creates a palindrome like 100...01
        if length % 2 == 1:
            palindrome = new_left_half + '0' * (length - len(new_left_half) - 1) + new_left_half[-2::-1]
        else:
            palindrome = new_left_half + '0' * (length - len(new_left_half)) + new_left_half[::-1]
        candidates.append(int(palindrome))
    else:
        if length % 2 == 1:
            palindrome = new_left_half + new_left_half[-2::-1]
        else:
            palindrome = new_left_half + new_left_half[::-1]
        candidates.append(int(palindrome))

    # Candidate 4: All 9's (e.g., 999...9)
    candidates.append(int('9' * (length - 1)))

    # Candidate 5: 10...01 (e.g., 100...01)
    candidates.append(int('1' + '0' * (length - 1) + '1'))

    # Remove the original number itself
    candidates = [c for c in candidates if c != num]

    # Find the closest palindrome
    closest = candidates[0]
    min_diff = abs(closest - num)

    for candidate in candidates[1:]:
        diff = abs(candidate - num)
        if diff < min_diff or (diff == min_diff and candidate < closest):
            min_diff = diff
            closest = candidate

    return str(closest)

