class Solution:
    def xorGame(self, nums: List[int]) -> bool:
        # Calculate XOR of all numbers
        xor_sum = 0
        for num in nums:
            xor_sum ^= num

        # If XOR is 0, Alice wins immediately
        if xor_sum == 0:
            return True

        # If XOR is not 0, Alice wins if number of elements is even
