def minimumDistance(points):
    n = len(points)

    def manhattan_distance(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def max_distance_after_removal(removed_idx):
        # If we remove one point, find max distance among remaining points
        if n == 2:
            return 0

        # Get all points except the removed one
        remaining = []
        for i in range(n):
            if i != removed_idx:
                remaining.append(points[i])

        # Find maximum Manhattan distance among remaining points
        max_dist = 0
        for i in range(len(remaining)):
            for j in range(i + 1, len(remaining)):
                dist = manhattan_distance(remaining[i], remaining[j])
                max_dist = max(max_dist, dist)

        return max_dist

    # Try removing each point and find the minimum maximum distance
    min_max_distance = float('inf')
    for i in range(n):
        max_dist = max_distance_after_removal(i)
        min_max_distance = min(min_max_distance, max_dist)

    return min_max_distance
